{
  "enabled": true,
  "host": "127.0.0.1",
  "port": 9343,
  "openBrowserOnStart": false,
  "requireLocalToken": true,
  "database": {
    "filename": ""
  },
  "historyRetention": {
    "maxEntries": 1000,
    "maxBodyBytes": 65536,
    "persistBodies": true
  },
  "telemetry": {
    "enabled": true,
    "collectionIntervalMs": 15000,
    "retentionDays": 30,
    "pruneIntervalMinutes": 60,
    "persistRawSnapshot": true,
    "gpu": {
      "enabled": true,
      "nvidiaDcgmExporterUrl": null,
      "commandTimeoutMs": 5000
    }
  },
  "localInferenceServer": {
    "port": 11435,
    "routingMode": "PreferLocal",
    "routes": [],
    "discoverLocalModels": true,
    "healthCheckIntervalMs": 15000,
    "localQueueTimeoutMs": 30000
  },
  "defaultMaxConcurrentRequests": 4
}

{
  "Rest": {
    "Hostname": "0.0.0.0",
    "Port": 9000,
    "Ssl": false,
    "RequireAuthentication": true
  },
  "Cors": {
    "Enabled": true,
    "AllowedOrigins": [
      "http://localhost:9100"
    ],
    "AllowedHeaders": [
      "Authorization",
      "Content-Type",
      "x-token",
      "x-tenant-guid",
      "x-tenant-id",
      "x-access-key"
    ],
    "AllowedMethods": [
      "GET",
      "POST",
      "PUT",
      "DELETE",
      "OPTIONS"
    ]
  },
  "WebSocket": {
    "Enabled": true,
    "Path": "/ws/v1/clients",
    "HeartbeatIntervalMs": 15000,
    "RequestTimeoutMs": 120000
  },
  "Routing": {
    "DefaultTimeoutMs": 300000,
    "LoadBalancingMode": "RoundRobin",
    "Adaptive": {
      "SampleCount": 2,
      "CapacityWeight": 45,
      "InFlightWeight": 30,
      "ClientWeight": 15,
      "HeartbeatWeight": 10
    }
  },
  "Database": {
    "Type": "Sqlite",
    "Filename": "data/xeno.db"
  },
  "Logging": {
    "ConsoleLogging": true,
    "FileLogging": true,
    "LogDirectory": "logs",
    "LogFilename": "xeno.log"
  },
  "Email": {
    "Enabled": false,
    "Provider": "Disabled",
    "FromAddress": "noreply@xenocloud.ai",
    "FromName": "Xeno",
    "ReplyToAddress": "support@xenocloud.ai",
    "SupportAddress": "support@xenocloud.ai",
    "ApplicationBaseUrl": "https://app.xenocloud.ai",
    "SubjectPrefix": "",
    "MaxBodyBytes": 262144,
    "Mailgun": {
      "Domain": "",
      "ApiKey": "",
      "Region": "US"
    },
    "File": {
      "Directory": "data/email-outbox"
    },
    "Notifications": {
      "NotifyPlatformAdministratorsOnTenantCreated": true,
      "NotifyPlatformAdministratorsOnUserJoined": true,
      "NotifyTenantAdministratorsOnUserJoined": true,
      "NotifyNewTenantAdministrator": true,
      "NotifyNewTenantMember": false,
      "PlatformAdministratorRecipients": []
    }
  },
  "Telemetry": {
    "Enable": true,
    "ServiceName": "xeno-server",
    "Metrics": {
      "Enable": true,
      "ExportIntervalMs": 15000,
      "IncludeTenantLabel": false,
      "ExportFleetTelemetry": true
    },
    "Traces": {
      "Enable": true,
      "SamplingRatio": 1.0,
      "PropagateToClient": true
    },
    "Logs": {
      "Enable": true
    },
    "Otlp": {
      "Endpoint": "http://localhost:4317",
      "Protocol": "grpc",
      "TimeoutMs": 10000,
      "Headers": null
    }
  }
}
